'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const teeth=[6,12,24],speeds=[2,1,.5],ids=['small','equal','large'];
let variant=OrionProgress.variant('gears'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,size=1,idler=false,solved=false,hintDepth=0,state='ready',history=[],saveFailed=false,paused=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches??false;
function target(v=variant,s=stage){return{speed:speeds[(v+s)%3],cw:!!((Math.floor(v/3)+s)%2)};}
function output(){return{speed:speeds[size],cw:idler};}
function description(d){return (d.cw?t('↻ Clockwise','↻ 順時針'):t('↺ Anticlockwise','↺ 逆時針'))+' · '+(d.speed===2?t('2× speed','2 倍速度'):d.speed===1?t('1× speed','相同速度'):t('½× speed','一半速度'));}
function resetTrial(){size=((variant+stage)%3+1)%3;idler=!target().cw;solved=false;hintDepth=0;state='ready';history=[];saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('gears')){variant=v;stage=0;resetTrial();}
function chooseSize(n){if(solved||!Number.isInteger(n)||n<0||n>2)return;size=n;state='changed';render();}
function toggleIdler(){if(solved)return;idler=!idler;state='changed';render();}
function matches(){const a=output(),b=target();return a.speed===b.speed&&a.cw===b.cw;}
function check(){if(solved)return;history.unshift(output());if(!matches()){state='wrong';render();return;}solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('motion');render();if(stage<2)$('next').focus();}
function hints(){const g=target(),n=teeth[speeds.indexOf(g.speed)];return[t('Watch the gold output wheel. Swap its size, then try adding the middle gear. What changes each time?','看看金色輸出輪。換大小，再試加入中間齒輪。每次有甚麼改變？'),t('Touching gears turn opposite ways. More output teeth means slower turns. A middle gear reverses direction again without changing the final speed ratio.','接觸的齒輪轉向相反。輸出輪齒數越多，轉得越慢。中間齒輪再反轉方向，但不改變最後的速度比例。'),t(`Use the ${n}-tooth output wheel and ${g.cw?'add':'remove'} the middle gear.`,`選擇 ${n} 齒輸出輪，並${g.cw?'加入':'移除'}中間齒輪。`)];}
function cog(x,n,cw,speed,color){const r=n*3,points=[];for(let i=0;i<n*4;i++){const a=(i/(n*4))*Math.PI*2,rad=r+([0,3].includes(i%4)?-3:3);points.push(`${Math.cos(a)*rad},${Math.sin(a)*rad}`);}return `<g transform="translate(${x} 112)"><g class="rotor" style="--period:${8/speed}s;--turn:${cw?360:-360}deg"><polygon points="${points.join(' ')}" fill="${color}" stroke="#f0d393" stroke-width="1.5"/><circle r="${r*.63}" fill="#132d34" stroke="#cfb274" stroke-width="2"/><path d="M0 -${r*.5}V${r*.5}M-${r*.5} 0H${r*.5}" stroke="${color}" stroke-width="5"/><circle cy="-${r*.78}" r="3" fill="#fff8d5"/></g><circle r="6" fill="#f6dfab"/></g>`;}
function render(){const g=target(),a=output(),complete=solved&&stage===2,count=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Gearkeeper’s Vault · Orion','齒輪守護者的密庫 · Orion');$('stageTitle').textContent=t(`Seal ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 道封印 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Gear seals restored · ${count} / 3`,`已修復 ${count} / 3 道齒輪封印`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
ids.forEach((id,i)=>{$(id).disabled=solved;$(id).setAttribute('aria-pressed',String(i===size));});$('idler').disabled=solved;$('idler').setAttribute('aria-pressed',String(idler));$('idler').textContent=idler?t('− Remove middle gear','− 移除中間齒輪'):t('+ Add middle gear','+ 加入中間齒輪');$('pause').textContent=paused?t('▶ Play rotation','▶ 播放轉動'):t('Ⅱ Pause rotation','Ⅱ 暫停轉動');$('diagram').classList.toggle('paused',paused);
$('goal').innerHTML=t('Required output','所需輸出')+`<strong>${description(g)}</strong>`;$('reading').innerHTML=t('Your gold output wheel','你的金色輸出輪')+`<strong>${description(a)}</strong>`;
const radius=teeth[size]*3,total=36+radius+(idler?72:0),x1=220-total/2,x2=x1+36+radius+(idler?72:0),xm=x1+72;
$('diagram').setAttribute('aria-label',t(`Driver: 12 teeth, clockwise, 1× speed. ${idler?'Middle gear: 12 teeth. ':''}Output: ${teeth[size]} teeth, ${description(a)}.`,`主動輪：12 齒，順時針，相同速度。${idler?'中間輪：12 齒。':''}輸出輪：${teeth[size]} 齒，${description(a)}。`));
$('diagram').innerHTML=`<svg viewBox="0 0 440 230" aria-hidden="true"><text x="220" y="20" text-anchor="middle" fill="#f0dab0" font-size="14">${t('Driver always turns ↻ at 1×','主動輪一直以 1 倍速度 ↻ 轉動')}</text>${cog(x1,12,true,1,'#85bab5')}${idler?cog(xm,12,false,1,'#b49b78'):''}${cog(x2,teeth[size],a.cw,a.speed,'#dfb867')}<text x="${x1}" y="205" text-anchor="middle" fill="#a9dcd3" font-size="13">${t('Driver','主動')} 12</text>${idler?`<text x="${xm}" y="223" text-anchor="middle" fill="#d1bea0" font-size="12">${t('Middle','中間')} 12</text>`:''}<text x="${x2}" y="205" text-anchor="middle" fill="#ffe0a0" font-size="13">${t('Output','輸出')} ${teeth[size]}</text></svg>`;
const msg={ready:t('Swap the output wheel and try the middle gear. Match the gold wheel’s direction AND speed.','更換輸出輪，試試中間齒輪。配對金色輪的方向和速度。'),changed:matches()?t('Both match! Unlock the seal.','兩項都配對了！打開封印吧。'):t('Compare the direction and speed with the required output.','比較目前的方向和速度，是否符合所需輸出。'),wrong:t('Not both matched yet. Change a gear and try again.','還未全部配對。換個齒輪再試一次。'),success:t('Perfect transmission! A gear seal opens.','傳動配對了！一道齒輪封印打開。')};$('feedback').textContent=msg[state];$('log').innerHTML=history.slice(0,3).map(d=>`<li>${description(d)} ${d.speed===g.speed&&d.cw===g.cw?'✓':'↻'}</li>`).join('')||`<li>${t('Checked designs appear here.','檢查過的設計會記錄在這裡。')}</li>`;
for(const id of ['check','retry'])$(id).hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('motion')?t('Motion Sigil saved in your collection.','傳動符印已存入收藏。'):'';}
ids.forEach((id,i)=>$(id).onclick=()=>chooseSize(i));$('idler').onclick=toggleIdler;$('pause').onclick=()=>{paused=!paused;render();};$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('small').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('gears',variant);observedVariant=OrionProgress.variant('gears');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('motion');render();};
function syncProgress(){const v=OrionProgress.variant('gears'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('motion')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
